import java.util.Scanner;

public class E {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int mod = 998244353;
        int n = sc.nextInt();
        long K = sc.nextLong();
        if (K >= n) {
            System.out.println(0);
            return;
        }
        int[][] factInv = precomputeFactorials(n, mod);
        if (K == 0) {
            System.out.println(factInv[0][n]);
            return;
        }
        long total = 0;
        for (int i = (int) (n - K); i >= 1; i--) {
            int sign = ((n - K - i) % 2 == 0) ? 1 : -1;
            long comb = C(n, i, mod, factInv);
            long powVal = pow(i, n, mod);
            long term = comb * powVal % mod;
            term = term * sign % mod;
            long comb2 = C((int) (n - i), (int) K, mod, factInv);
            total = (total + term * comb2) % mod;
        }
        total = (total * 2) % mod;
        System.out.println(total);
    }

    public static long pow(long base, int exp, int mod) {
        long result = 1;
        long b = base % mod;
        for (int i = 0; i < 64; i++) {
            if (((exp >> i) & 1) == 1) result = result * b % mod;
            b = b * b % mod;
        }
        return result;
    }

    public static long C(int n, int r, int mod, int[][] factInv) {
        if (n < 0 || r < 0 || r > n) return 0;
        return (long) factInv[0][n] * factInv[1][r] % mod * factInv[1][n - r] % mod;
    }

    public static int[][] precomputeFactorials(int n, int mod) {
        int[] fact = new int[n + 1];
        int[] invFact = new int[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int) ((long) fact[i - 1] * i % mod);
        }
        long invNFact = pow(fact[n], mod - 2, mod);
        invFact[n] = (int) invNFact;
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = (int) ((long) invFact[i + 1] * (i + 1) % mod);
        }
        return new int[][] { fact, invFact };
    }
}
